            if (!(",{semantic-cache-tiers},").Contains("," + (context.Product?.Id ?? "") + ",")) { return false; }
            var messages = context.Request.Body?.As(preserveContent: true)?["messages"] as JArray;
            if (messages == null) { return false; }
            int turns = 0;
            foreach (var message in messages) {
                var item = message as JObject;
                if (item == null) { return false; }
                var role = (string)item["role"] ?? "";
                if (role != "system" && role != "developer") { turns++; }
            }
            return turns == 1;
