                <set-variable name="semanticCacheLookupMicroUsd" value="@{
                    var messages = (JArray)context.Request.Body.As(preserveContent: true)["messages"];
                    long chars = 0;
                    foreach (var message in messages) {
                        var item = (JObject)message;
                        var role = (string)item["role"] ?? "";
                        var content = item["content"];
                        if (role == "system" || role == "developer" || content == null) { continue; }
                        if (content.Type == JTokenType.String) { chars += ((string)content).Length; continue; }
                        var parts = content as JContainer;
                        if (parts == null) { continue; }
                        foreach (var token in parts.Descendants()) {
                            if (token.Type == JTokenType.String) { chars += ((string)token).Length; }
                        }
                    }
                    var price = double.Parse("{semantic-cache-embedding-price}");
                    return (int)Math.Max(1, Math.Ceiling(((chars + 3) / 4) * price));
                }" />

                <set-variable name="semanticCachePartition" value="@{
                    var scope = (string)context.Variables["semanticCacheScope"];
                    var owner = context.Subscription?.Id ?? "anonymous";
                    var endUser = context.Variables.GetValueOrDefault("endUser", "");
                    if (endUser != "") { owner += "/" + endUser; }
                    var key = scope == "plan" ? "plan:" + (context.Product?.Id ?? "none")
                        : scope == "user" ? "user:" + owner
                        : "session:" + owner + "/" + context.Variables.GetValueOrDefault("session", "no-session");
                    var instructions = new System.Text.StringBuilder();
                    foreach (var message in (JArray)context.Request.Body.As(preserveContent: true)["messages"]) {
                        var item = (JObject)message;
                        var role = (string)item["role"] ?? "";
                        if (role == "system" || role == "developer") { instructions.Append(role).Append(':').Append(item["content"]?.ToString() ?? "").Append('\n'); }
                    }
                    if (instructions.Length == 0) { return key + "/sys:none"; }
                    using (var sha = System.Security.Cryptography.SHA256.Create()) {
                        var hash = sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(instructions.ToString()));
                        return key + "/sys:" + BitConverter.ToString(hash, 0, 4).Replace("-", "").ToLowerInvariant();
                    }
                }" />

                    @(context.Product?.Id ?? "none")
                    @(context.Variables.GetValueOrDefault("servedModel", ""))
                    @(context.Variables.GetValueOrDefault("budgetEpoch", ""))
                    @((string)context.Variables["semanticCachePartition"])
